  // Database struct to hold the connection details and handle operations.
  type Database struct {
  	DB *sql.DB
  }

  // NewDatabase creates a new instance of the database client.
  func NewDatabase(dataSourceName string) (*Database, error) {
  	db, err := sql.Open("postgres", dataSourceName)
  	if err != nil {
  		return nil, errors.Wrap(err, "failed to open database connection")
  	}
  	if err = db.Ping(); err != nil {
  		return nil, errors.Wrap(err, "failed to ping the database")
  	}
  	return &Database{DB: db}, nil
  }

  // Close closes the database connection.
  func (d *Database) Close() error {
  	return d.DB.Close()
  }

  // CreateMediaFile inserts a new media file record into the database.
  func (d *Database) CreateMediaFile(ctx context.Context, mediaFile MediaFile) (string, error) {
  	id := uuid.New().String()

  	query := `INSERT INTO media_files (id, name, path, size) VALUES ($1, $2, $3, $4)`
  	_, err := d.DB.ExecContext(ctx, query, id, mediaFile.Name, mediaFile.Path, mediaFile.Size)
  	if err != nil {
  		return "", errors.Wrap(err, "failed to insert media file")
  	}

  	return id, nil
  }

  // GetMediaFiles fetches all media files from the database.
  func (d *Database) GetMediaFiles(ctx context.Context) ([]MediaFile, error) {
  	query := `SELECT id, name, path, size FROM media_files`
  	rows, err := d.DB.QueryContext(ctx, query)
  	if err != nil {
  		return nil, errors.Wrap(err, "failed to fetch media files")
  	}
  	defer rows.Close()

  	var mediaFiles []MediaFile
  	for rows.Next() {
  		var file MediaFile
  		if err := rows.Scan(&file.ID, &file.Name, &file.Path, &file.Size); err != nil {
  			return nil, errors.Wrap(err, "failed to scan media file")
  		}
  		mediaFiles = append(mediaFiles, file)
  	}

  	if err := rows.Err(); err != nil {
  		return nil, errors.Wrap(err, "error during rows iteration")
  	}

  	return mediaFiles, nil
  }

  // DeleteMediaFile removes a media file record from the database.
  func (d *Database) DeleteMediaFile(ctx context.Context, id string) error {
  	query := `DELETE FROM media_files WHERE id = $1`
  	if _, err := d.DB.ExecContext(ctx, query, id); err != nil {
  		return errors.Wrap(err, "failed to delete media file")
  	}

  	return nil
  }
}

