  package pkg

  import (
  	"errors"
  	"fmt"
  	"io/ioutil"
  	"os"
  	"path/filepath"
  )

  type MediaManager struct {
  	MediaDir string
  }

  func NewMediaManager(mediaDir string) (*MediaManager, error) {
  	if _, err := os.Stat(mediaDir); os.IsNotExist(err) {
  		return nil, errors.New("media directory does not exist")
  	}
  	return &MediaManager{MediaDir: mediaDir}, nil
  }

  func (mm *MediaManager) UploadMedia(filePath string) error, {
  	content, err := ioutil.ReadFile(filePath)
  	if err != nil {
  		return err
  	}

  	ext := filepath.Ext(filePath)
  	newFilePath := filepath.Join(mm.MediaDir, contentHash(content)+ext)

  	err = ioutil.WriteFile(newFilePath, content, 0644)
  	if err != nil {
  		return err
  	}
  	return nil
  }

  func (mm *MediaManager) OrganizeMedia() error {
  	return filepath.Walk(mm.MediaDir, func(path string, info os.FileInfo, err error) error {
  		if err != nil {
  			return err
  		}
  		ext := filepath.Ext(path)
  		targetDir := filepath.Join(mm.MediaDir, ext[1:])
  		err = os.MkdirAll(targetDir, 0755)
  		if err != nil {
  			return err
  		}
  		newPath := filepath.Join(targetDir, info.Name())
  		return os.Rename(path, newPath)
  	})
  }

  func (mm *MediaManager) RetrieveMedia(ext string) ([]string, error) {
  	matches, err := filepath.Glob(filepath.Join(mm.MediaDir, ext))
  	if err != nil {
  		return nil, err
  	}
  	return matches, nil
  }
}

