  package pkg

  import (
  	"fmt"
  	"net/http"
  	"sync"

  	"github.com/gorilla/mux"
  )

  type Device struct {
  	ID       string `json:"id"`
  	Name     string `json:"name"`
  	Location string `json:"location"`
  }

  type APIClient struct {
  	httpClient *http.Client
  	baseURL    string
  	mu         sync.Mutex
  	devices    map[string]Device
  }

  func NewAPIClient(baseURL string) (*APIClient, error) {
  	client := &http.Client{}
  	return &APIClient{
  		httpClient: client,
  		baseURL:    baseURL,
  		devices:    make(map[string]Device),
  	}, nil
  }

  func (ac *APIClient) DetectDevices() ([]Device, error) {
  	var devices []Device
  	resp, err := ac.httpClient.Get(ac.baseURL + "/devices")
  	if err != nil {
  		return nil, fmt.Errorf("failed to fetch devices: %w", err)
  	}
  	defer resp.Body.Close()

  	// Parse response and populate devices slice
  	if err = json.NewDecoder(resp.Body).Decode(&devices); err != nil {
  		return nil, fmt.Errorf("failed to decode response: %w", err)
  	}

  	ac.mu.Lock()
  	for _, device := range devices {
  		ac.devices[device.ID] = device
  	}
  	ac.mu.Unlock()

  	return devices, nil
  }

  func (ac *APIClient) StreamingSession(deviceID string) error {
  	resp, err := ac.httpClient.Get(ac.baseURL + "/devices/" + deviceID + "/stream")
  	if err != nil {
  		return fmt.Errorf("failed to start streaming session: %w", err)
  	}
  	defer resp.Body.Close()

  	// Handle streaming logic
  	return nil
  }

  func (ac *APIClient) Authenticate(username, password string) error {
  	resp, err := ac.httpClient.PostForm(ac.baseURL+"/auth", url.Values{
  		"username": {username},
  		"password": {password},
  	})
  	if err != nil {
  		return fmt.Errorf("failed to authenticate: %w", err)
  	}
  	defer resp.Body.Close()

  	// Handle authentication logic
  	if resp.StatusCode != http.StatusOK {
  		return fmt.Errorf("authentication failed: %s", resp.Status)
  	}

  	return nil
  }

  func (ac *APIClient) StartServer(port int) error {
  	r := mux.NewRouter()
  	r.HandleFunc("/api/devices", ac.handleDevices).Methods(http.MethodGet)
  	r.HandleFunc("/api/authenticate", ac.handleAuthenticate).Methods(http.MethodPost)

  	server := &http.Server{
  		Addr:    fmt.Sprintf(":%d", port),
  		Handler: r,
  	}

  	return server.ListenAndServe()
  }

  func (ac *APIClient) handleDevices(w http.ResponseWriter, r *http.Request) {
  	devices, err := ac.DetectDevices()
  	if err != nil {
  		http.Error(w, err.Error(), http.StatusInternalServerError)
  		return
  	}
  	json.NewEncoder(w).Encode(devices)
  }

  func (ac *APIClient) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
  	username := r.FormValue("username")
  	password := r.FormValue("password")
  	if err := ac.Authenticate(username, password); err != nil {
  		http.Error(w, err.Error(), http.StatusUnauthorized)
  		return
  	}
  	w.WriteHeader(http.StatusOK)
  }
}

