  // Node struct represents the data structure for a node in a graph.
  type Node struct {
  	ID      int
  	Value   string
  	Neighbours map[int]*Node
  }

  // NewNode creates a new node with the given ID and value.
  func (n *Node) NewNode(id int, value string) *Node {
  	return &Node{
  		ID:       id,
  		Value:    value,
  		Neighbours: make(map[int]*Node),
  	}
  }

  // AddNeighbour adds a neighbour to the node.
  func (n *Node) AddNeighbour(neighbour *Node) error {
  	if _, exists := n.Neighbours[neighbour.ID]; exists {
  		return errors.New("neighbour already exists")
  	}
  	n.Neighbours[neighbour.ID] = neighbour
  	return nil
  }

  // RemoveNeighbour removes a neighbour from the node.
  func (n *Node) RemoveNeighbour(neighbourID int) error {
  	if _, exists := n.Neighbours[neighbourID]; !exists {
  		return errors.New("neighbour does not exist")
  	}
  	delete(n.Neighbours, neighbourID)
   return nil
  }

  // GetNeighbours returns a slice of all neighbours.
  func (n *Node) GetNeighbours() []*Node {
  	var neighbours []*Node
  	for _, neighbour := range n.Neighbours {
  		neighbours = append(neighbours, neighbour)
  	}
  	return neighbours
  }
}

