  package logging

  import (
      "github.com/coreos/go-systemd/journal"
      "sync"
  )

  var logger *journal.Journal

  func InitJournalLogger() error {
      var err error
      logger, err = journal.NewOS()
      if err != nil {
          return err
      }
      go func() {
          sync.WaitGroup{}.Add(1)
          defer sync.WaitGroup{}.Done()
          for {
              select {
              case entry := <-logger.GetChan():
                  // Process journal entries as needed
              case sig := <-logger.GetExitChan():
                  logger.Stop()
                  return sig.Err
              }
          }
      }()
      return nil
  }

  func LogError(message string, err error) error {
      if logger == nil {
          return err
      }
      entry := &journal.Entry{
          Headers: journal.Fields{
              "MESSAGE": message,
              "_PID":    []byte{0x6f, 0x8c, 0x63, 0xb9},
              "PRIORITY": journal.Pri.err,
          },
      }
      return logger.Send(entry)
  }

  func LogInfo(message string) error {
      if logger == nil {
          return nil
      }
      entry := &journal.Entry{
          Headers: journal.Fields{
              "MESSAGE": message,
              "_PID":    []byte{0x6f, 0x8c, 0x63, 0xb9},
              "PRIORITY": journal.Pri.info,
          },
      }
      return logger.Send(entry)
  }
}

