package media

import (
    "errors"
    "log"
    "os"

    "github.com/fsnotify/fsnotify"
)

// Config represents the configuration settings for the media server.
type Config struct {
    Port     int
    MaxFiles int
}

// NewServer initializes and starts a new media streaming server.
func NewServer(config *Config) error {
    // Basic setup
    log.Println("Starting media streaming server...")

    // Watch for changes in media files
    watcher, err := fsnotify.NewWatcher()
    if err != nil {
        return fmt.Errorf("failed to create watcher: %w", err)
    }
    defer watcher.Close()

    done := make(chan bool)
    go func() {
        for {
            select {
            case event, ok := <-watcher.Events:
                if !ok {
                    return
                }
                log.Println("event:", event.Name, "state:", event.Op.String())
                // Handle file change events
            case err, ok := <-watcher.Errors:
                if !ok {
                    return
                }
                log.Println("error:", err)
            }
        }
    }()

    // Add media directory to watcher
    err = watcher.Add("/path/to/media")
    if err != nil {
        return fmt.Errorf("failed to watch media directory: %w", err)
    }

    select {
    case <-done:
    case <-time.After(time.Duration(config.MaxFiles) * time.Second):
    }

    log.Println("Server shutting down...")
    return nil
}

