  	if err != nil {
  		return fmt.Errorf("failed to start streaming session: %w", err)
  	}
  	defer resp.Body.Close()

  	// Handle streaming logic
  	return nil
  }

  func (ac *APIClient) Authenticate(username, password string) error {
  	resp, err := ac.httpClient.PostForm(ac.baseURL+"/auth", url.Values{
  		"username": {username},
  		"password": {password},
  	})
  	if err != nil {
  		return fmt.Errorf("failed to authenticate: %w", err)
  	}
  	defer resp.Body.Close()

  	// Handle authentication logic
  	if resp.StatusCode != http.StatusOK {
  		return fmt.Errorf("authentication failed: %s", resp.Status)
  	}

  	return nil
  }

  func (ac *APIClient) StartServer(port int) error {
  	r := mux.NewRouter()
  	r.HandleFunc("/api/devices", ac.handleDevices).Methods(http.MethodGet)
  	r.HandleFunc("/api/authenticate", ac.handleAuthenticate).Methods(http.MethodPost)

  	server := &http.Server{
  		Addr:    fmt.Sprintf(":%d", port),
  		Handler: r,
  	}

  	return server.ListenAndServe()
  }

  func (ac *APIClient) handleDevices(w http.ResponseWriter, r *http.Request) {
  	devices, err := ac.DetectDevices()
  	if err != nil {
