  }

  func LoadConfig(filepath string) (*Config, error) {
  	file, err := os.Open(filepath)
  	if err != nil {
  		return nil, fmt.Errorf("failed to open config file: %w", err)
  	}
  	defer file.Close()

  	content, err := ioutil.ReadAll(file)
  	if err != nil {
  		return nil, fmt.Errorf("failed to read config file: %w", err)
  	}

  	var config Config
  	err = json.Unmarshal(content, &config)
  	if err != nil {
  		return nil, fmt.Errorf("failed to unmarshal config file: %w", err)
  	}

  	return &config, nil
  }

  func UpdateRule(config *Config, ruleName string, newValue string) error {
  	if config.Rules == nil {
  		config.Rules = make(map[string]string)
  	}
  	config.Rules[ruleName] = newValue

  	tmpFile, err := ioutil.TempFile("", "config_*.json")
  	if err != nil {
  		return fmt.Errorf("failed to create temp file: %w", err)
  	}
  	defer os.Remove(tmpFile.Name())

  	err = json.NewEncoder(tmpFile).Encode(config)
  	if err != nil {
  		return fmt.Errorf("failed to encode config to temp file: %w", err)
  	}

  	err = os.Rename(tmpFile.Name(), "config.json")
  	if err != nil {
  		return fmt.Errorf("failed to rename temp file to config.json: %w", err)
  	}

  	return nil
  }
}

